guidedExercise.solutionCode:
from collections import deque

def topological_order(tasks):
    by_id = {task.task_id: task for task in tasks}
    if len(by_id) != len(tasks):
        raise ValueError('DUPLICATE_TASK_ID')
    indegree = {key: len(task.dependencies) for key, task in by_id.items()}
    children = {key: [] for key in by_id}
    for task in tasks:
        for dependency in task.dependencies:
            if dependency not in by_id:
                raise ValueError('UNKNOWN_DEPENDENCY')
            children[dependency].append(task.task_id)
    ready = deque(sorted(key for key, degree in indegree.items() if degree == 0))
    result = []
    while ready:
        current = ready.popleft()
        result.append(current)
        for child in sorted(children[current]):
            indegree[child] -= 1
            if indegree[child] == 0:
                ready.append(child)
    if len(result) != len(tasks):
        raise ValueError('DEPENDENCY_CYCLE')
    return result

guidedExercise.unitTests:
assert topological_order([Task('collect'), Task('draft', ('collect',)), Task('review', ('collect',)), Task('publish', ('draft','review'))])[0] == 'collect'
try:
    topological_order([Task('a', ('b',)), Task('b', ('a',))])
except ValueError as error:
    assert str(error) == 'DEPENDENCY_CYCLE'
else:
    raise AssertionError('cycle must be rejected')
